function validate(input) {
  const [{ Transactions = [] }] = input;
  const ids = new Set();
  for (const [id, day, amount] of Transactions) {
    if (id === null || day === null || amount === null) return 'Every transaction needs an id, a day and an amount.';
    if (ids.has(id)) return `transaction_id ${id} appears twice.`;
    ids.add(id);
    if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(day)) return `day ${day} must look like 2021-04-03 15:57:28.`;
  }
  return null;
}

