function generate(rand, size) {
  const small = size === 'small';
  const pad = n => String(n).padStart(2, '0');
  const count = small ? Math.floor(rand() * 9) : 2000;
  const dates = small ? ['2021-04-03', '2021-04-04', '2021-04-28'] : [];
  if (!small) for (let m = 1; m <= 12; m++) for (let d = 1; d <= 28; d += 2) dates.push(`2021-${pad(m)}-${pad(d)}`);
  const amounts = [0, 10, 21, 40, 57, 58, 58];
  const clock = () => {
    const edge = rand();
    if (edge < 0.15) return '00:00:00';
    if (edge < 0.3) return '23:59:59';
    return `${pad(Math.floor(rand() * 24))}:${pad(Math.floor(rand() * 60))}:${pad(Math.floor(rand() * 60))}`;
  };
  // Distinct ids in shuffled order, with gaps.
  const ids = [];
  for (let i = 0, id = 0; i < count; i++) { id += 1 + Math.floor(rand() * 3); ids.push(id); }
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Transactions = ids.map(id => [
    id,
    `${dates[Math.floor(rand() * dates.length)]} ${clock()}`,
    small ? amounts[Math.floor(rand() * amounts.length)] : Math.floor(rand() * 60),
  ]);
  return [{ Transactions }];
}
